@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap');

:root {
  --primary: #0051C3;
  --primary-hover: #003e99;
  --accent: #DE5052;
  --accent-hover: #c94042;
  --bg-main: #ffffff;
  --bg-alt: #f8f9fa;
  --bg-dark: #0f172a;
  --text-main: #111827;
  --text-muted: #4b5563;
  --text-light: #9ca3af;
  --border: #e5e7eb;
  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Inter', sans-serif;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 1rem;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-main);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--text-main);
  line-height: 1.2;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color 0.2s ease;
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

ul {
  list-style: none;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Typography */
.text-center { text-align: center; }
.text-muted { color: var(--text-muted); }
.text-primary { color: var(--primary); }
.text-accent { color: var(--accent); }

.h1 { font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 800; letter-spacing: -0.02em; }
.h2 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 700; letter-spacing: -0.01em; }
.h3 { font-size: 1.5rem; font-weight: 600; }
.lead { font-size: 1.125rem; color: var(--text-muted); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  font-family: var(--font-body);
  font-size: 1rem;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}
.btn-primary:hover { background-color: var(--primary-hover); }

.btn-accent {
  background-color: var(--accent);
  color: white;
}
.btn-accent:hover { background-color: var(--accent-hover); }

.btn-outline {
  background-color: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}
.btn-outline:hover {
  background-color: var(--primary);
  color: white;
}

.btn-light {
  background-color: white;
  color: var(--primary);
}
.btn-light:hover { background-color: var(--bg-alt); }

/* Layout Helpers */
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-2 { gap: 0.5rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-8 { gap: 2rem; }
.grid { display: grid; }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }

/* Spacing */
.py-12 { padding-top: 3rem; padding-bottom: 3rem; }
.py-20 { padding-top: 5rem; padding-bottom: 5rem; }
.py-24 { padding-top: 6rem; padding-bottom: 6rem; }
.mt-8 { margin-top: 2rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-8 { margin-bottom: 2rem; }
.mb-12 { margin-bottom: 3rem; }

/* Header & Nav */
.header {
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  z-index: 50;
  padding: 1rem 0;
}

.header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.logo i { font-size: 1.75rem; color: var(--accent); }

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.desktop-nav a {
  font-weight: 500;
  color: var(--text-muted);
}
.desktop-nav a:hover, .desktop-nav a.active { color: var(--primary); }

.nav-actions { display: flex; align-items: center; gap: 1rem; }

.hamburger {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  color: var(--text-main);
  cursor: pointer;
}

/* Mobile Nav Drawer */
.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 80%;
  max-width: 400px;
  height: 100vh;
  background-color: white;
  box-shadow: -4px 0 15px rgba(0,0,0,0.1);
  z-index: 100;
  padding: 2rem;
  transition: right 0.3s ease;
  display: flex;
  flex-direction: column;
}

.mobile-nav.open { right: 0; }
.mobile-nav .close-btn {
  align-self: flex-end;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  margin-bottom: 2rem;
}
.mobile-nav .nav-links {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 2rem;
}
.mobile-nav .nav-links a { color: var(--text-main); }
.overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background: rgba(0,0,0,0.5);
  z-index: 90;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.overlay.open { opacity: 1; pointer-events: all; }

/* Hero Section */
.hero {
  padding: 6rem 0 4rem;
  background: linear-gradient(135deg, #f0f5ff 0%, #ffffff 100%);
  position: relative;
  overflow: hidden;
}
.hero-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background-color: rgba(0, 81, 195, 0.1);
  color: var(--primary);
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.875rem;
  margin-bottom: 1.5rem;
}
.hero-visual {
  margin-top: 4rem;
  background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.hero-visual-pattern {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(var(--border) 1px, transparent 1px);
  background-size: 20px 20px;
  opacity: 0.5;
}

/* Features */
.section-bg-alt { background-color: var(--bg-alt); }
.feature-card {
  background: white;
  padding: 2rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.feature-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}
.feature-icon {
  width: 48px;
  height: 48px;
  background-color: rgba(0, 81, 195, 0.1);
  color: var(--primary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
}

/* Stats */
.stats-banner {
  background-color: var(--primary);
  color: white;
  padding: 4rem 0;
}
.stat-item {
  text-align: center;
}
.stat-value {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}
.stat-label {
  font-weight: 500;
  opacity: 0.9;
}

/* How it works */
.step-item {
  position: relative;
  padding-left: 3rem;
  margin-bottom: 2rem;
}
.step-number {
  position: absolute;
  left: 0;
  top: 0;
  width: 2rem;
  height: 2rem;
  background-color: var(--primary);
  color: white;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
}
.step-item h4 { margin-bottom: 0.5rem; }

/* Testimonials */
.testimonial-carousel {
  max-width: 800px;
  margin: 0 auto;
  position: relative;
  background: white;
  padding: 3rem;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
}
.testimonial-card { display: none; text-align: center; }
.testimonial-card.active { display: block; animation: fadeIn 0.5s ease; }
.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  color: var(--text-main);
}
.testimonial-author { font-weight: 600; color: var(--primary); }
.testimonial-role { font-size: 0.875rem; color: var(--text-muted); }
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
}
.carousel-btn:hover { background: var(--primary); color: white; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* Pricing */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}
.toggle-switch {
  position: relative;
  width: 50px;
  height: 26px;
  background-color: var(--primary);
  border-radius: 13px;
  cursor: pointer;
}
.toggle-thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  background-color: white;
  border-radius: 50%;
  transition: transform 0.3s ease;
}
.toggle-switch.annual .toggle-thumb { transform: translateX(24px); }
.save-badge {
  background-color: rgba(222, 80, 82, 0.1);
  color: var(--accent);
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 700;
}
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  align-items: stretch;
}
.pricing-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  display: flex;
  flex-direction: column;
}
.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary);
  position: relative;
}
.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
}
.price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  margin: 1rem 0;
}
.price span { font-size: 1rem; font-weight: 500; color: var(--text-muted); }
.pricing-features {
  margin-top: 2rem;
  margin-bottom: 2rem;
  flex-grow: 1;
}
.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.pricing-features i { color: var(--primary); font-size: 1.25rem; }

/* FAQ */
.faq-container {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1.5rem 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--text-muted);
}
.faq-item.active .faq-answer {
  max-height: 200px;
  padding-bottom: 1.5rem;
}
.faq-icon {
  transition: transform 0.3s ease;
}
.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

/* CTA Block */
.cta-block {
  background-color: var(--bg-dark);
  color: white;
  text-align: center;
  padding: 6rem 0;
}
.cta-block h2 { color: white; }

/* Contact Form */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
}
.form-group {
  margin-bottom: 1.5rem;
}
.form-label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 500;
}
.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 1rem;
  transition: border-color 0.2s ease;
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}
textarea.form-control {
  resize: vertical;
  min-height: 120px;
}
.form-error {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 0.5rem;
  display: none;
}
.form-group.invalid .form-control { border-color: var(--accent); }
.form-group.invalid .form-error { display: block; }

.form-success {
  display: none;
  background-color: rgba(16, 185, 129, 0.1);
  color: #059669;
  padding: 1rem;
  border-radius: var(--radius-sm);
  margin-bottom: 1.5rem;
  border: 1px solid #10b981;
}
.form-success.show { display: block; }

/* Footer */
.footer {
  background-color: var(--bg-dark);
  color: var(--text-light);
  padding: 5rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 4rem;
}
.footer-logo {
  color: white;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
}
.footer-logo i { color: var(--accent); }
.footer-col h4 {
  color: white;
  margin-bottom: 1.5rem;
  font-size: 1rem;
}
.footer-links li { margin-bottom: 0.75rem; }
.footer-links a:hover { color: white; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 992px) {
  .pricing-cards { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .stats-banner .grid-cols-4 { grid-template-columns: repeat(2, 1fr); gap: 2rem; }
}

@media (max-width: 768px) {
  .desktop-nav, .nav-actions .btn:not(.hamburger) { display: none; }
  .hamburger { display: block; }
  .contact-grid { grid-template-columns: 1fr; }
  .grid-cols-2 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 576px) {
  .stats-banner .grid-cols-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero { padding: 4rem 0 2rem; }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. Mobile Navigation Toggle
  const hamburger = document.getElementById('hamburger-btn');
  const mobileNav = document.getElementById('mobile-nav');
  const closeBtn = document.getElementById('close-nav-btn');
  const overlay = document.getElementById('overlay');

  if (hamburger && mobileNav && closeBtn && overlay) {
    const toggleNav = () => {
      mobileNav.classList.toggle('open');
      overlay.classList.toggle('open');
    };

    hamburger.addEventListener('click', toggleNav);
    closeBtn.addEventListener('click', toggleNav);
    overlay.addEventListener('click', toggleNav);
  }

  // 2. Testimonial Carousel
  const prevBtn = document.getElementById('carousel-prev');
  const nextBtn = document.getElementById('carousel-next');
  const cards = document.querySelectorAll('.testimonial-card');

  if (cards.length > 0 && prevBtn && nextBtn) {
    let currentIndex = 0;

    const showCard = (index) => {
      cards.forEach((card, i) => {
        if (i === index) {
          card.classList.add('active');
        } else {
          card.classList.remove('active');
        }
      });
    };

    prevBtn.addEventListener('click', () => {
      currentIndex = (currentIndex === 0) ? cards.length - 1 : currentIndex - 1;
      showCard(currentIndex);
    });

    nextBtn.addEventListener('click', () => {
      currentIndex = (currentIndex === cards.length - 1) ? 0 : currentIndex + 1;
      showCard(currentIndex);
    });
  }

  // 3. Pricing Toggle
  const pricingToggle = document.getElementById('pricing-toggle');
  const starterPrice = document.getElementById('starter-price');
  const premiumPrice = document.getElementById('premium-price');

  if (pricingToggle && starterPrice && premiumPrice) {
    pricingToggle.addEventListener('click', () => {
      pricingToggle.classList.toggle('annual');
      const isAnnual = pricingToggle.classList.contains('annual');

      // Values based on 20% savings for annual
      // Starter: $29.99/mo -> $23.99/mo
      // Premium: $69.99/mo -> $55.99/mo

      if (isAnnual) {
        starterPrice.innerHTML = '$23.99<span>/mo</span>';
        premiumPrice.innerHTML = '$55.99<span>/mo</span>';
      } else {
        starterPrice.innerHTML = '$29.99<span>/mo</span>';
        premiumPrice.innerHTML = '$69.99<span>/mo</span>';
      }
    });
  }

  // 4. FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  if (faqItems.length > 0) {
    faqItems.forEach(item => {
      const question = item.querySelector('.faq-question');
      question.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Close all
        faqItems.forEach(faq => faq.classList.remove('active'));

        // Open clicked if it wasn't active
        if (!isActive) {
          item.classList.add('active');
        }
      });
    });
  }

  // 5. Contact Form Validation
  const contactForm = document.getElementById('contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', (e) => {
      e.preventDefault();
      let isValid = true;

      const fields = ['name', 'email', 'company', 'message'];

      fields.forEach(fieldId => {
        const input = document.getElementById(fieldId);
        const group = input.closest('.form-group');

        if (!input.value.trim()) {
          group.classList.add('invalid');
          isValid = false;
        } else {
          group.classList.remove('invalid');

          if (fieldId === 'email') {
            const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
            if (!emailRegex.test(input.value)) {
              group.classList.add('invalid');
              isValid = false;
            }
          }
        }
      });

      if (isValid) {
        document.getElementById('form-success').classList.add('show');
        contactForm.reset();

        // Hide success message after 5 seconds
        setTimeout(() => {
          document.getElementById('form-success').classList.remove('show');
        }, 5000);
      }
    });

    // Remove invalid class on input
    const inputs = contactForm.querySelectorAll('.form-control');
    inputs.forEach(input => {
      input.addEventListener('input', () => {
        input.closest('.form-group').classList.remove('invalid');
      });
    });
  }
});
